-- AMNote Web / API_AMNOTE_WEB
-- Master Grid: AP_UTILITY_CHECK_ALLOC
-- Detail Grid: AP_UTILITY_CHECK_ALLOC_DETAIL
-- Can be run more than once: existing GRID_ID + FIELD_NAME rows are preserved.
-- Execute on the manager database where sys_grid_column resides.

INSERT INTO sys_grid_column (
    GRID_ID, FIELD_NAME, LABEL_TEXT, CAPTION,
    IS_VISIBLE, VISIBLE_INDEX, COLUMN_WIDTH,
    IS_FIXED, FIXED_POSITION, ALLOW_HIDING,
    ALIGN, FORMAT_TYPE, SORT_ORDER, SORT_INDEX,
    CREATE_BY, CREATE_AT, UPDATE_BY, UPDATE_AT, ISDEL
)
SELECT
    cfg.GRID_ID, cfg.FIELD_NAME, cfg.LABEL_TEXT, cfg.CAPTION,
    cfg.IS_VISIBLE, cfg.VISIBLE_INDEX, cfg.COLUMN_WIDTH,
    cfg.IS_FIXED, cfg.FIXED_POSITION, cfg.ALLOW_HIDING,
    cfg.ALIGN, cfg.FORMAT_TYPE, NULL, NULL,
    'SYSTEM', NOW(), 'SYSTEM', NOW(), '0'
FROM (
SELECT 'AP_UTILITY_CHECK_ALLOC' AS GRID_ID, 'SERVICES_CHIT_ID' AS FIELD_NAME, 'SERVICES_CHIT_ID' AS LABEL_TEXT, 'Mã ID chứng từ' AS CAPTION, '0' AS IS_VISIBLE, 0 AS VISIBLE_INDEX, 100 AS COLUMN_WIDTH, '0' AS IS_FIXED, NULL AS FIXED_POSITION, '0' AS ALLOW_HIDING, 'center' AS ALIGN, NULL AS FORMAT_TYPE
    UNION ALL
    SELECT 'AP_UTILITY_CHECK_ALLOC' AS GRID_ID, 'SERVICES_CHIT_NO' AS FIELD_NAME, 'SERVICES_CHIT_NO' AS LABEL_TEXT, 'Số chứng từ' AS CAPTION, '1' AS IS_VISIBLE, 1 AS VISIBLE_INDEX, 155 AS COLUMN_WIDTH, '0' AS IS_FIXED, NULL AS FIXED_POSITION, '1' AS ALLOW_HIDING, 'left' AS ALIGN, NULL AS FORMAT_TYPE
    UNION ALL
    SELECT 'AP_UTILITY_CHECK_ALLOC' AS GRID_ID, 'CHIT_YMD' AS FIELD_NAME, 'CHIT_YMD' AS LABEL_TEXT, 'Ngày giao dịch' AS CAPTION, '1' AS IS_VISIBLE, 2 AS VISIBLE_INDEX, 120 AS COLUMN_WIDTH, '0' AS IS_FIXED, NULL AS FIXED_POSITION, '1' AS ALLOW_HIDING, 'center' AS ALIGN, 'date' AS FORMAT_TYPE
    UNION ALL
    SELECT 'AP_UTILITY_CHECK_ALLOC' AS GRID_ID, 'VAT_CHIT_NO' AS FIELD_NAME, 'VAT_CHIT_NO' AS LABEL_TEXT, 'Số hóa đơn' AS CAPTION, '1' AS IS_VISIBLE, 3 AS VISIBLE_INDEX, 130 AS COLUMN_WIDTH, '0' AS IS_FIXED, NULL AS FIXED_POSITION, '1' AS ALLOW_HIDING, 'left' AS ALIGN, NULL AS FORMAT_TYPE
    UNION ALL
    SELECT 'AP_UTILITY_CHECK_ALLOC' AS GRID_ID, 'VAT_YMD' AS FIELD_NAME, 'VAT_YMD' AS LABEL_TEXT, 'Ngày hóa đơn' AS CAPTION, '1' AS IS_VISIBLE, 4 AS VISIBLE_INDEX, 120 AS COLUMN_WIDTH, '0' AS IS_FIXED, NULL AS FIXED_POSITION, '1' AS ALLOW_HIDING, 'center' AS ALIGN, 'date' AS FORMAT_TYPE
    UNION ALL
    SELECT 'AP_UTILITY_CHECK_ALLOC' AS GRID_ID, 'CUSTOMER_ID' AS FIELD_NAME, 'CUSTOMER_ID' AS LABEL_TEXT, 'Mã ID khách hàng' AS CAPTION, '0' AS IS_VISIBLE, 5 AS VISIBLE_INDEX, 100 AS COLUMN_WIDTH, '0' AS IS_FIXED, NULL AS FIXED_POSITION, '0' AS ALLOW_HIDING, 'left' AS ALIGN, NULL AS FORMAT_TYPE
    UNION ALL
    SELECT 'AP_UTILITY_CHECK_ALLOC' AS GRID_ID, 'CUSTOMER_CD' AS FIELD_NAME, 'CUSTOMER_CD' AS LABEL_TEXT, 'Mã khách hàng' AS CAPTION, '1' AS IS_VISIBLE, 6 AS VISIBLE_INDEX, 145 AS COLUMN_WIDTH, '0' AS IS_FIXED, NULL AS FIXED_POSITION, '1' AS ALLOW_HIDING, 'left' AS ALIGN, NULL AS FORMAT_TYPE
    UNION ALL
    SELECT 'AP_UTILITY_CHECK_ALLOC' AS GRID_ID, 'CONTENTS' AS FIELD_NAME, 'CONTENTS' AS LABEL_TEXT, 'Diễn giải' AS CAPTION, '1' AS IS_VISIBLE, 7 AS VISIBLE_INDEX, 340 AS COLUMN_WIDTH, '0' AS IS_FIXED, NULL AS FIXED_POSITION, '1' AS ALLOW_HIDING, 'left' AS ALIGN, NULL AS FORMAT_TYPE
    UNION ALL
    SELECT 'AP_UTILITY_CHECK_ALLOC' AS GRID_ID, 'TOTAL_COST' AS FIELD_NAME, 'TOTAL_COST' AS LABEL_TEXT, 'Tổng chi phí' AS CAPTION, '1' AS IS_VISIBLE, 8 AS VISIBLE_INDEX, 155 AS COLUMN_WIDTH, '0' AS IS_FIXED, NULL AS FIXED_POSITION, '1' AS ALLOW_HIDING, 'right' AS ALIGN, 'number0' AS FORMAT_TYPE
    UNION ALL
    SELECT 'AP_UTILITY_CHECK_ALLOC' AS GRID_ID, 'COST_NOT_YET_ALLOCATED' AS FIELD_NAME, 'COST_NOT_YET_ALLOCATED' AS LABEL_TEXT, 'Chi phí chưa phân bổ' AS CAPTION, '1' AS IS_VISIBLE, 9 AS VISIBLE_INDEX, 170 AS COLUMN_WIDTH, '0' AS IS_FIXED, NULL AS FIXED_POSITION, '1' AS ALLOW_HIDING, 'right' AS ALIGN, 'number0' AS FORMAT_TYPE
    UNION ALL
    SELECT 'AP_UTILITY_CHECK_ALLOC' AS GRID_ID, 'COST_NOW_ALLOCATES' AS FIELD_NAME, 'COST_NOW_ALLOCATES' AS LABEL_TEXT, 'Chi phí phân bổ kỳ này' AS CAPTION, '0' AS IS_VISIBLE, 10 AS VISIBLE_INDEX, 160 AS COLUMN_WIDTH, '0' AS IS_FIXED, NULL AS FIXED_POSITION, '0' AS ALLOW_HIDING, 'right' AS ALIGN, 'number0' AS FORMAT_TYPE
    UNION ALL
    SELECT 'AP_UTILITY_CHECK_ALLOC' AS GRID_ID, 'COST_REMAIN' AS FIELD_NAME, 'COST_REMAIN' AS LABEL_TEXT, 'Chi phí còn lại' AS CAPTION, '1' AS IS_VISIBLE, 11 AS VISIBLE_INDEX, 155 AS COLUMN_WIDTH, '0' AS IS_FIXED, NULL AS FIXED_POSITION, '1' AS ALLOW_HIDING, 'right' AS ALIGN, 'number0' AS FORMAT_TYPE
    UNION ALL
    SELECT 'AP_UTILITY_CHECK_ALLOC_DETAIL' AS GRID_ID, 'SERVICES_CHIT_ID' AS FIELD_NAME, 'SERVICES_CHIT_ID' AS LABEL_TEXT, 'Mã ID chứng từ dịch vụ' AS CAPTION, '0' AS IS_VISIBLE, 0 AS VISIBLE_INDEX, 100 AS COLUMN_WIDTH, '0' AS IS_FIXED, NULL AS FIXED_POSITION, '0' AS ALLOW_HIDING, 'left' AS ALIGN, NULL AS FORMAT_TYPE
    UNION ALL
    SELECT 'AP_UTILITY_CHECK_ALLOC_DETAIL' AS GRID_ID, 'SERVICES_CHIT_CD' AS FIELD_NAME, 'SERVICES_CHIT_CD' AS LABEL_TEXT, 'Mã chứng từ dịch vụ' AS CAPTION, '0' AS IS_VISIBLE, 1 AS VISIBLE_INDEX, 130 AS COLUMN_WIDTH, '0' AS IS_FIXED, NULL AS FIXED_POSITION, '0' AS ALLOW_HIDING, 'left' AS ALIGN, NULL AS FORMAT_TYPE
    UNION ALL
    SELECT 'AP_UTILITY_CHECK_ALLOC_DETAIL' AS GRID_ID, 'INVENTORY_CHIT_ID' AS FIELD_NAME, 'INVENTORY_CHIT_ID' AS LABEL_TEXT, 'Mã ID chứng từ phân bổ' AS CAPTION, '0' AS IS_VISIBLE, 2 AS VISIBLE_INDEX, 110 AS COLUMN_WIDTH, '0' AS IS_FIXED, NULL AS FIXED_POSITION, '0' AS ALLOW_HIDING, 'left' AS ALIGN, NULL AS FORMAT_TYPE
    UNION ALL
    SELECT 'AP_UTILITY_CHECK_ALLOC_DETAIL' AS GRID_ID, 'INVENTORY_CHIT_CD' AS FIELD_NAME, 'INVENTORY_CHIT_CD' AS LABEL_TEXT, 'Mã chứng từ phân bổ' AS CAPTION, '0' AS IS_VISIBLE, 3 AS VISIBLE_INDEX, 150 AS COLUMN_WIDTH, '0' AS IS_FIXED, NULL AS FIXED_POSITION, '0' AS ALLOW_HIDING, 'left' AS ALIGN, NULL AS FORMAT_TYPE
    UNION ALL
    SELECT 'AP_UTILITY_CHECK_ALLOC_DETAIL' AS GRID_ID, 'CHIT_TYPE' AS FIELD_NAME, 'CHIT_TYPE' AS LABEL_TEXT, 'Loại chứng từ' AS CAPTION, '0' AS IS_VISIBLE, 4 AS VISIBLE_INDEX, 115 AS COLUMN_WIDTH, '0' AS IS_FIXED, NULL AS FIXED_POSITION, '0' AS ALLOW_HIDING, 'center' AS ALIGN, NULL AS FORMAT_TYPE
    UNION ALL
    SELECT 'AP_UTILITY_CHECK_ALLOC_DETAIL' AS GRID_ID, 'CHIT_NO' AS FIELD_NAME, 'CHIT_NO' AS LABEL_TEXT, 'Số chứng từ' AS CAPTION, '1' AS IS_VISIBLE, 5 AS VISIBLE_INDEX, 165 AS COLUMN_WIDTH, '0' AS IS_FIXED, NULL AS FIXED_POSITION, '1' AS ALLOW_HIDING, 'left' AS ALIGN, NULL AS FORMAT_TYPE
    UNION ALL
    SELECT 'AP_UTILITY_CHECK_ALLOC_DETAIL' AS GRID_ID, 'CHIT_YMD' AS FIELD_NAME, 'CHIT_YMD' AS LABEL_TEXT, 'Ngày giao dịch' AS CAPTION, '1' AS IS_VISIBLE, 6 AS VISIBLE_INDEX, 140 AS COLUMN_WIDTH, '0' AS IS_FIXED, NULL AS FIXED_POSITION, '1' AS ALLOW_HIDING, 'center' AS ALIGN, 'date' AS FORMAT_TYPE
    UNION ALL
    SELECT 'AP_UTILITY_CHECK_ALLOC_DETAIL' AS GRID_ID, 'AMOUNT_SHARE' AS FIELD_NAME, 'AMOUNT_SHARE' AS LABEL_TEXT, 'Tiền phân bổ' AS CAPTION, '1' AS IS_VISIBLE, 7 AS VISIBLE_INDEX, 185 AS COLUMN_WIDTH, '0' AS IS_FIXED, NULL AS FIXED_POSITION, '1' AS ALLOW_HIDING, 'right' AS ALIGN, 'number0' AS FORMAT_TYPE
) AS cfg
WHERE NOT EXISTS (
    SELECT 1 FROM sys_grid_column s
    WHERE s.GRID_ID = cfg.GRID_ID
      AND s.FIELD_NAME = cfg.FIELD_NAME
);

SELECT GRID_ID, FIELD_NAME, CAPTION, IS_VISIBLE, VISIBLE_INDEX
FROM sys_grid_column
WHERE GRID_ID IN ('AP_UTILITY_CHECK_ALLOC', 'AP_UTILITY_CHECK_ALLOC_DETAIL')
ORDER BY GRID_ID, VISIBLE_INDEX;
